/* eslint-env jest */
'use strict';

const os = require('os');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Err', () => {
    let logger;
    let stream;
    let jestFakeTimers;
    let baseRecord;

    beforeEach(() => {
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/err')(),
            ],
        });

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен перезаписать record.err', () => {
        let err = new TypeError('test');
        err.stack = '<stacktrace>';
        err.status = 500;

        logger.info({ err }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            err: {
                name: 'TypeError',
                message: 'test',
                status: 500,
                stack: '<stacktrace>',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен обрабатывать record.err без стектрейса', () => {
        let err = { message: 'test' };

        logger.info({ err }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            err: {
                message: 'test',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без record.err', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith(baseRecord);
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('сохраняет cause из пришедшей ошибки, если это честные ошибки', () => {
        const root = new Error('root cause');
        root.stack = '<root stacktrace>';
        const intermediate = new Error('intermediate cause', { cause: root });
        intermediate.stack = '<intermediate stacktrace>';
        const err = new Error('test', { cause: intermediate });
        err.stack = '<stacktrace>';

        logger.error(err);

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            err: {
                name: 'Error',
                message: 'test',
                stack: '<stacktrace>',
                cause: {
                    name: 'Error',
                    message: 'intermediate cause',
                    stack: '<intermediate stacktrace>',
                    cause: {
                        name: 'Error',
                        message: 'root cause',
                        stack: '<root stacktrace>',
                    },
                },
            },
            level: 50,
            levelName: 'ERROR',
            msg: 'test',
            msgFormat: 'test',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('сохраняет cause из пришедшей ошибки, если это просто строки', () => {
        const cause = 'cause';
        const err = new Error('test', { cause });
        err.stack = '<stacktrace>';

        logger.error(err);

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            err: {
                name: 'Error',
                message: 'test',
                stack: '<stacktrace>',
                cause: 'cause',
            },
            level: 50,
            levelName: 'ERROR',
            msg: 'test',
            msgFormat: 'test',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен обрабатывать объекты без hasOwnProperty', () => {
        const err = Object.create(null);
        err.name = 'Error';
        err.message = 'test';
        err.stack = '<stacktrace>';

        logger.extendFields({ err });
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            err: {
                name: 'Error',
                message: 'test',
                stack: '<stacktrace>',
            },
        });
    });

    it('должен обрабатывать объект с циклической ссылкой', () => {
        const circularObj = {};
        circularObj.name = 'circular object';
        circularObj.err = new Error('error');
        circularObj.err.message = 'error';
        circularObj.err.stack = '<error-stack>';
        circularObj.self = circularObj;

        logger.extendFields({ circularObj });
        logger.info('circular object');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            msg: 'circular object',
            msgFormat: 'circular object',
            circularObj: {
                name: 'circular object',
                err: {
                    name: 'Error',
                    message: 'error',
                    stack: '<error-stack>',
                },
                self: circularObj,
            },
        });
    });

    it('должен обрабатывать ошибку с нестандартными свойствами', () => {
        const customErr = new TypeError('custom');
        customErr.stack = '<custom-stack>';
        customErr.code = 500;
        customErr.details = { foo: 'bar' };

        logger.extendFields({ err: customErr });
        logger.info('custom error');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            msg: 'custom error',
            msgFormat: 'custom error',
            err: {
                name: 'TypeError',
                message: 'custom',
                stack: '<custom-stack>',
                code: 500,
                details: { foo: 'bar' },
            },
        });
    });

    it('должен обрабатывать ошибку с вложенным не-ошибкой объектом', () => {
        const nestedObjErr = new Error('nested');
        nestedObjErr.stack = '<nested-stack>';
        nestedObjErr.data = {
            notError: {
                message: 'not an error',
            },
        };

        logger.extendFields({ err: nestedObjErr });
        logger.info('nested object error');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            msg: 'nested object error',
            msgFormat: 'nested object error',
            err: {
                name: 'Error',
                message: 'nested',
                stack: '<nested-stack>',
                data: {
                    notError: {
                        message: 'not an error',
                    },
                },
            },
        });
    });
});
